        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#CLANDESTINITE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Clandestinit&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HERESIE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;r&#233;sie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#ILLUMINATION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Illumination&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#OUBLI&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Oubli&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#RESTAURATION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Restauration&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#REVELATION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;R&#233;v&#233;lation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#SEDITION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;S&#233;dition&lt;/a&gt;.&lt;/td&gt;
